/* Restore a pink and blue discovery palette, separately from feature text. */
.dyk-slim{background:linear-gradient(135deg,color-mix(in srgb,var(--hp-cobalt) 35%,var(--hp-ink)),var(--hp-midnight))}
.dyk-slim h2{color:var(--hp-pink);-webkit-text-stroke:0;text-shadow:none}
.dyk-slim .dyk-copy :is(h3,.dyk-title){color:var(--hp-coral)}
.dyk-slim .dyk-cta{color:var(--hp-sky)}
.dyk-slim .dyk-media{outline-color:var(--hp-pink)}
.dyk-slim h2::after{background:var(--hp-sky)}
.dyk-slim .dyk-arrow,.dyk-slim .dyk-pause{color:var(--hp-sky);border-color:var(--hp-pink)}
.dyk-slim :is(a,button):focus-visible{outline-color:var(--hp-pink)}
</style>
